    public function getFactHistVitacoras($criteria = null, PropelPDO $con = null)
    {
        $partial = $this->collFactHistVitacorasPartial && !$this->isNew();
        if (null === $this->collFactHistVitacoras || null !== $criteria  || $partial) {
            if ($this->isNew() && null === $this->collFactHistVitacoras) {
                // return empty collection
                $this->initFactHistVitacoras();
            } else {
                $collFactHistVitacoras = FactHistVitacoraQuery::create(null, $criteria)
                    ->filterByFactHist($this)
                    ->find($con);
                if (null !== $criteria) {
                    if (false !== $this->collFactHistVitacorasPartial && count($collFactHistVitacoras)) {
                      $this->initFactHistVitacoras(false);

                      foreach ($collFactHistVitacoras as $obj) {
                        if (false == $this->collFactHistVitacoras->contains($obj)) {
                          $this->collFactHistVitacoras->append($obj);
                        }
                      }

                      $this->collFactHistVitacorasPartial = true;
                    }

                    $collFactHistVitacoras->getInternalIterator()->rewind();

                    return $collFactHistVitacoras;
                }

                if ($partial && $this->collFactHistVitacoras) {
                    foreach ($this->collFactHistVitacoras as $obj) {
                        if ($obj->isNew()) {
                            $collFactHistVitacoras[] = $obj;
                        }
                    }
                }

                $this->collFactHistVitacoras = $collFactHistVitacoras;
                $this->collFactHistVitacorasPartial = false;
            }
        }

        return $this->collFactHistVitacoras;
