     * @param PropelPDO $con Optional connection object
     * @return FactHist The current object (for fluent API support)
     */
    public function setFactHistVitacoras(PropelCollection $factHistVitacoras, PropelPDO $con = null)
    {
        $factHistVitacorasToDelete = $this->getFactHistVitacoras(new Criteria(), $con)->diff($factHistVitacoras);


        $this->factHistVitacorasScheduledForDeletion = $factHistVitacorasToDelete;

        foreach ($factHistVitacorasToDelete as $factHistVitacoraRemoved) {
            $factHistVitacoraRemoved->setFactHist(null);
        }

        $this->collFactHistVitacoras = null;
        foreach ($factHistVitacoras as $factHistVitacora) {
            $this->addFactHistVitacora($factHistVitacora);
        }

        $this->collFactHistVitacoras = $factHistVitacoras;
        $this->collFactHistVitacorasPartial = false;

        return $this;
    }

    /**
