     * @throws PropelException
     */
    public function countFactHistVitacoras(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collFactHistVitacorasPartial && !$this->isNew();
        if (null === $this->collFactHistVitacoras || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collFactHistVitacoras) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getFactHistVitacoras());
            }
            $query = FactHistVitacoraQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByFactHist($this)
                ->count($con);
        }

        return count($this->collFactHistVitacoras);
    }

    /**
