     * @param    FactHistVitacora $l FactHistVitacora
     * @return FactHist The current object (for fluent API support)
     */
    public function addFactHistVitacora(FactHistVitacora $l)
    {
        if ($this->collFactHistVitacoras === null) {
            $this->initFactHistVitacoras();
            $this->collFactHistVitacorasPartial = true;
        }

        if (!in_array($l, $this->collFactHistVitacoras->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddFactHistVitacora($l);

            if ($this->factHistVitacorasScheduledForDeletion and $this->factHistVitacorasScheduledForDeletion->contains($l)) {
                $this->factHistVitacorasScheduledForDeletion->remove($this->factHistVitacorasScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	FactHistVitacora $factHistVitacora The factHistVitacora object to add.
     */
    protected function doAddFactHistVitacora($factHistVitacora)
    {
        $this->collFactHistVitacoras[]= $factHistVitacora;
        $factHistVitacora->setFactHist($this);
