    /**
     * @param	FactHistVitacora $factHistVitacora The factHistVitacora object to remove.
     * @return FactHist The current object (for fluent API support)
     */
    public function removeFactHistVitacora($factHistVitacora)
    {
        if ($this->getFactHistVitacoras()->contains($factHistVitacora)) {
            $this->collFactHistVitacoras->remove($this->collFactHistVitacoras->search($factHistVitacora));
            if (null === $this->factHistVitacorasScheduledForDeletion) {
                $this->factHistVitacorasScheduledForDeletion = clone $this->collFactHistVitacoras;
                $this->factHistVitacorasScheduledForDeletion->clear();
            }
            $this->factHistVitacorasScheduledForDeletion[]= clone $factHistVitacora;
            $factHistVitacora->setFactHist(null);
        }

        return $this;
    }

